/**
 * RFC 7807 Problem Details: the registered problem families and the one body
 * builder. A family's `type` URN, status, title and fixed detail are never
 * spelled anywhere else in the service.
 *
 * Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
 */

export const PROBLEM_TYPE_URN_PREFIX = "urn:cruftfree:error:";

export type FieldErrorLocation = "path" | "query" | "body";
export type FieldErrorCode = "required" | "unknown_field" | "repeated" | "invalid";

/** One field-level `request-validation` error: where, which field, which code. */
export interface FieldError {
  location: FieldErrorLocation;
  field: string;
  message: string;
  code: FieldErrorCode;
}

export interface ProblemDetails {
  type: string;
  title: string;
  status: number;
  detail: string;
  instance: string;
  errors?: FieldError[];
  violations?: string[];
  [extension: string]: unknown;
}

export type ProblemFamily =
  | "bad-request"
  | "unauthorized"
  | "missing-tenant"
  | "forbidden"
  | "not-found"
  | "entity-not-found"
  | "conflict"
  | "cascade-restriction"
  | "validation"
  | "request-validation"
  | "rate-limit-exceeded"
  | "internal"
  | "service-unavailable"
  | "timeout"
  | "revocation-unavailable"
  | "model-limit-exceeded"
  | "model-output-invalid"
  | "model-tool-denied"
  | "model-attachment-unsupported"
  | "model-approval-pending"
  ;

export interface RegisteredProblem {
  readonly family: ProblemFamily;
  readonly urn: string;
  readonly status: number;
  readonly title: string;
  readonly fixedDetail: string | null;
  readonly extensionMembers: readonly string[];
  /** The member a bare-status raise carries its detail in, as its one entry. */
  readonly statusDetailMember: string | null;
}

