/** The family a bare HTTP status maps to when nothing more specific raised it. */
export const GENERIC_PROBLEM_FAMILY_BY_STATUS: Readonly<Record<number, ProblemFamily>> = {
  400: "bad-request",
  401: "unauthorized",
  403: "forbidden",
  404: "not-found",
  409: "conflict",
  422: "validation",
  429: "rate-limit-exceeded",
  500: "internal",
  503: "service-unavailable",
  504: "timeout",
};

/**
 * The one message each field-error code carries; a framework's own message
 * embeds fragments of the received value and is never returned.
 */
export const FIELD_ERROR_MESSAGES: Readonly<Record<FieldErrorCode, string>> = {
  "required": "This value is required.",
  "unknown_field": "This field is not part of the request.",
  "repeated": "This parameter was given more than once.",
  "invalid": "This value does not satisfy its declared type or constraints.",
};

const ERRORS_MEMBER = "errors";
const VIOLATIONS_MEMBER = "violations";

/** A field error whose message is the registered text for its code. */
export function fieldError(
  location: FieldErrorLocation,
  field: string,
  code: FieldErrorCode,
): FieldError {
  return { location, field, message: FIELD_ERROR_MESSAGES[code], code };
}

export interface ProblemExtras {
  detail?: string;
  errors?: readonly FieldError[];
  violations?: readonly string[];
  extensions?: Readonly<Record<string, unknown>>;
}

/**
 * The body of one problem, rendered from the registered *family*.
 *
 * A family with a fixed detail takes none from the caller; any other requires
 * one. The extension members are exactly the family's declared set.
 */
export function problemBody(
  family: ProblemFamily,
  instance: string,
  extras: ProblemExtras = {},
): ProblemDetails {
  const problem = PROBLEM_TYPES[family];
  if (problem === undefined) {
    throw new Error(
      `'${String(family)}' is not a registered framework problem type. ` +
        `Registered families: ${Object.keys(PROBLEM_TYPES).join(', ')}.`,
    );
  }
  let detail: string;
  if (problem.fixedDetail !== null) {
    if (extras.detail !== undefined) {
      throw new Error(
        `Problem family '${family}' carries a fixed detail and takes none from the caller.`,
      );
    }
    detail = problem.fixedDetail;
  } else {
    if (extras.detail === undefined) {
      throw new Error(`Problem family '${family}' requires a detail.`);
    }
    detail = extras.detail;
  }
  const members: Record<string, unknown> = { ...(extras.extensions ?? {}) };
  if (extras.errors !== undefined) {
    members[ERRORS_MEMBER] = [...extras.errors];
  }
  if (extras.violations !== undefined) {
    members[VIOLATIONS_MEMBER] = [...extras.violations];
  }
  const supplied = Object.keys(members).sort();
  const declared = [...problem.extensionMembers].sort();
  if (supplied.join('\u0000') !== declared.join('\u0000')) {
    throw new Error(
      `Problem family '${family}' declares extension members [${declared.join(', ')}]; ` +
        `the caller supplied [${supplied.join(', ')}].`,
    );
  }
  for (const name of [ERRORS_MEMBER, VIOLATIONS_MEMBER]) {
    const member = members[name];
    if (Array.isArray(member) && member.length === 0) {
      throw new Error(`Problem family '${family}' was given an empty '${name}' member.`);
    }
  }
  return {
    type: problem.urn,
    title: problem.title,
    status: problem.status,
    detail,
    instance,
    ...members,
  };
}

/**
 * The body of a bare HTTP status (a guard, the rate limiter, a pipe): the
 * registered generic family for *status*, or the composed `http-<status>` type
 * for a status the registry does not hold. A family with a fixed detail never
 * carries the raiser's text; a family naming a status-detail member carries the
 * detail there too, as its one entry.
 */
export function statusProblemBody(status: number, instance: string, detail: string): ProblemDetails {
  const family = GENERIC_PROBLEM_FAMILY_BY_STATUS[status];
  if (family === undefined) {
    return declaredProblemBody(
      `${PROBLEM_TYPE_URN_PREFIX}http-${String(status)}`,
      `HTTP ${String(status)}`,
      status,
      detail,
      instance,
    );
  }
  const problem = PROBLEM_TYPES[family];
  if (problem.fixedDetail !== null) {
    return problemBody(family, instance);
  }
  const member = problem.statusDetailMember;
  return problemBody(
    family,
    instance,
    member === null ? { detail } : { detail, extensions: { [member]: [detail] } },
  );
}

/** A declared exception's problem body: its URN was composed by the shared algorithm. */
export function declaredProblemBody(
  type: string,
  title: string,
  status: number,
  detail: string,
  instance: string,
): ProblemDetails {
  if (!type.startsWith(PROBLEM_TYPE_URN_PREFIX)) {
    throw new Error(`A declared problem type must start with '${PROBLEM_TYPE_URN_PREFIX}', got '${type}'.`);
  }
  return { type, title, status, detail, instance };
}
